export function makeTable(headerDefined) {
  return { kind: 'table', entries: new Map(), headerDefined }
}

export function makeArray() {
  return { kind: 'array', items: [] }
}

export function makeArrayOfTables() {
  return { kind: 'array-of-tables', items: [] }
}

/** Joins path segments the way error messages and `keys` paths render them. */
export function formatPath(segments) {
  let out = ''
  for (const seg of segments) {
    if (Object.prototype.hasOwnProperty.call(seg, 'key')) {
      out += (out === '' ? '' : '.') + seg.key
    } else {
      out += `[${seg.index}]`
    }
  }
  return out
}
"}

