 * Navigation and assignment for dotted names against the document tree: walking
 * through tables (auto-vivifying, or stepping into the last element of an array
 * of tables), and the distinct rules headers and key assignments each apply at
 * the final segment.
 */
import { ConfigError } from './errors.js'
import { makeTable, makeArrayOfTables, formatPath } from './nodes.js'

/**
 * Walks all but the last of `names` starting from `table`, creating tables
 * along the way. Returns the table the last segment should act on, plus the
 * full path segments to that last segment (for error messages).
 */
function walkIntermediate(table, names, basePathSegments, lineNo) {
  let current = table
  const pathSoFar = basePathSegments.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    pathSoFar.push({ key: name })
    const existing = current.entries.get(name)
    if (existing === undefined) {
      const t = makeTable(false)
      current.entries.set(name, t)
      current = t
    } else if (existing.kind === 'table') {
      current = existing
    } else if (existing.kind === 'array-of-tables') {
      current = existing.items[existing.items.length - 1]
    } else {
      throw new ConfigError(lineNo, `${formatPath(pathSoFar)} is not a table`)
    }
  }
  const lastName = names[names.length - 1]
  return { table: current, lastName, lastPath: pathSoFar.concat({ key: lastName }) }
}

/** Assigns `valueNode` at the dotted `names` path inside `table`, rejecting a repeat key. */
export function assignDotted(table, names, valueNode, basePathSegments, lineNo) {
  const { table: parent, lastName, lastPath } = walkIntermediate(table, names, basePathSegments, lineNo)
  if (parent.entries.has(lastName)) {
    throw new ConfigError(lineNo, `key ${formatPath(lastPath)} is defined twice`)
  }
  parent.entries.set(lastName, valueNode)
}

/** Makes the table named by a `[name]` header current, creating it if needed. */
export function enterHeaderTable(root, names, lineNo) {
  const { table: parent, lastName, lastPath } = walkIntermediate(root, names, [], lineNo)
  const existing = parent.entries.get(lastName)
  if (existing === undefined) {
    const t = makeTable(true)
    parent.entries.set(lastName, t)
    return { table: t, path: lastPath }
  }
  if (existing.kind !== 'table') {
    throw new ConfigError(lineNo, `${formatPath(lastPath)} is not a table`)
  }
  if (existing.headerDefined) {
    throw new ConfigError(lineNo, `table ${formatPath(lastPath)} is defined twice`)
  }
  existing.headerDefined = true
  return { table: existing, path: lastPath }
}

/** Appends a fresh table to the array of tables named by a `[[name]]` header. */
export function enterHeaderArray(root, names, lineNo) {
  const { table: parent, lastName, lastPath } = walkIntermediate(root, names, [], lineNo)
  let container = parent.entries.get(lastName)
  if (container === undefined) {
    container = makeArrayOfTables()
    parent.entries.set(lastName, container)
  } else if (container.kind !== 'array-of-tables') {
    throw new ConfigError(lineNo, `${formatPath(lastPath)} is not an array of tables`)
  }
  const t = makeTable(true)
  container.items.push(t)
  return { table: t, path: lastPath }
}
"}

