{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-XHJacQ/src/line-cursor.js","content":"/**
 * A cursor over one directive line: the primitive reads shared by names,
 * headers and values (whitespace and comment skipping, quoted strings, bare
 * name words).
 */
import { ConfigError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/

export class LineCursor {
  constructor(text, lineNo) {
    this.text = text
    this.pos = 0
    this.lineNo = lineNo
  }

  atEnd() {
    return this.pos >= this.text.length
  }

  peek() {
    return this.text[this.pos]
  }

  peekAt(n) {
    return this.text[this.pos + n]
  }

  skipWsTabs() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  /** Skips spaces and tabs, then treats a following `#`/`;` as ending the line. */
  skipToBoundary() {
    this.skipWsTabs()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) this.pos = this.text.length
  }

  fail(reason) {
    throw new ConfigError(this.lineNo, reason)
  }

  /** Reads a dotted name: bare words or quoted strings joined by `.`. */
  readDottedName() {
    const names = []
    while (true) {
      this.skipToBoundary()
      if (this.atEnd()) this.fail('expected a name')
      const ch = this.peek()
      let name
      if (ch === '"') name = this.readBasicStringBody()
      else if (ch === "'") name = this.readLiteralStringBody()
      else if (NAME_CHAR.test(ch)) {
        const start = this.pos
        while (!this.atEnd() && NAME_CHAR.test(this.peek())) this.pos++
        name = this.text.slice(start, this.pos)
      } else {
        this.fail('expected a name')
      }
      names.push(name)
      this.skipToBoundary()
      if (this.peek() === '.') {
        this.pos++
        continue
      }
      break
    }
    return names
  }

  /** Reads a `"..."` string, decoding its escapes. Assumes the cursor is at the opening quote. */
  readBasicStringBody() {
    this.pos++
    let out = ''
    while (true) {
      if (this.atEnd()) this.fail('unterminated string')
      const ch = this.text[this.pos]
      if (ch === '"') {
        this.pos++
        return out
      }
      if (ch === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
        const esc = this.text[this.pos]
        switch (esc) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            const hex = this.text.slice(this.pos + 1, this.pos + 5)
            if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
              out += String.fromCharCode(parseInt(hex, 16))
              this.pos += 5
            } else {
              this.fail('invalid escape \\u')
            }
            break
          }
          default:
            this.fail(`invalid escape \\${esc}`)
        }
      } else {
        out += ch
