const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`
)

/** Returns a value node for a bare token, or throws by returning null (caller reports the error). */
export function classifyBareToken(token) {
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(token)) return { kind: 'integer', value: parseIntToken(token) }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
    return { kind: 'float', value: parseFloatToken(token) }
  }
  return null
}

function parseIntToken(token) {
  const negative = token[0] === '-'
  const digits = token.replace(/^[+-]/, '').replace(/_/g, '')
  let value = BigInt(digits)
  if (negative) value = -value
  return value
}

function parseFloatToken(token) {
  return Number(token.replace(/_/g, ''))
}
"}

