import { makeArray, makeTable } from './nodes.js'
import { assignDotted } from './table-ops.js'

const BARE_STOP = new Set([' ', '\t', ',', ']', '}'])

export function readValue(cursor, pathSegments) {
  cursor.skipToBoundary()
  if (cursor.atEnd()) cursor.fail('expected a value')
  const ch = cursor.peek()
  if (ch === ',' || ch === ']' || ch === '}') cursor.fail('expected a value')
  if (ch === '"') return { kind: 'string', value: cursor.readBasicStringBody() }
  if (ch === "'") return { kind: 'string', value: cursor.readLiteralStringBody() }
  if (ch === '[') return readArray(cursor, pathSegments)
  if (ch === '{') return readInlineTable(cursor, pathSegments)
  return readBareValue(cursor)
}

function readBareValue(cursor) {
  const start = cursor.pos
  while (!cursor.atEnd() && !BARE_STOP.has(cursor.text[cursor.pos])) cursor.pos++
  const token = cursor.text.slice(start, cursor.pos)
  const value = classifyBareToken(token)
  if (value === null) cursor.fail(`invalid value ${token}`)
  return value
}

