  cursor.pos++ // consume '['
  cursor.skipToBoundary()
  const items = []
  if (cursor.peek() === ']') {
    cursor.pos++
    return { kind: 'array', items }
  }
  let index = 0
  while (true) {
    items.push(readValue(cursor, pathSegments.concat({ index })))
    index++
    cursor.skipToBoundary()
    if (cursor.atEnd()) cursor.fail('unterminated array')
    const ch = cursor.peek()
    if (ch === ',') {
      cursor.pos++
      cursor.skipToBoundary()
      if (cursor.atEnd()) cursor.fail('unterminated array')
      if (cursor.peek() === ']') {
        cursor.pos++
        return { kind: 'array', items }
      }
      continue
    }
    if (ch === ']') {
      cursor.pos++
      return { kind: 'array', items }
    }
    cursor.fail('unterminated array')
  }
}

function readInlineTable(cursor, pathSegments) {
  cursor.pos++ // consume '{'
  const table = makeTable(true)
  cursor.skipToBoundary()
  if (cursor.peek() === '}') {
    cursor.pos++
    return table
  }
  while (true) {
