    cursor.skipToBoundary()
    if (cursor.atEnd() || cursor.peek() !== '=') cursor.fail('expected = in an inline table')
    cursor.pos++
    cursor.skipToBoundary()
    const valuePath = pathSegments.concat(names.map((n) => ({ key: n })))
    const value = readValue(cursor, valuePath)
    assignDotted(table, names, value, pathSegments, cursor.lineNo)
    cursor.skipToBoundary()
    if (cursor.atEnd()) cursor.fail('unterminated inline table')
    const ch = cursor.peek()
