function parseHeaderLine(cursor, root) {
  const isArray = cursor.peekAt(1) === '['
  cursor.pos += isArray ? 2 : 1
  cursor.skipToBoundary()
  const names = cursor.readDottedName()
  cursor.skipToBoundary()

  if (isArray) {
    if (cursor.peek() !== ']' || cursor.peekAt(1) !== ']') cursor.fail('unterminated table header')
    cursor.pos += 2
  } else {
    if (cursor.peek() !== ']') cursor.fail('unterminated table header')
    cursor.pos += 1
  }

  cursor.skipToBoundary()
  if (!cursor.atEnd()) cursor.fail('trailing text after a table header')

  return isArray ? enterHeaderArray(root, names, cursor.lineNo) : enterHeaderTable(root, names, cursor.lineNo)
}

function parseKeyValueLine(cursor, currentTable, currentPath) {
  const names = cursor.readDottedName()
  cursor.skipToBoundary()
  if (cursor.peek() !== '=') cursor.fail('expected key = value')
  cursor.pos++
  cursor.skipToBoundary()

  const valuePath = currentPath.concat(names.map((n) => ({ key: n })))
  const value = readValue(cursor, valuePath)
  cursor.skipToBoundary()
  if (!cursor.atEnd()) cursor.fail('trailing text after a value')

  assignDotted(currentTable, names, value, currentPath, cursor.lineNo)
}

