{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-XHJacQ/src/json-output.js","content":"/** Renders a parsed document tree as indented, key-sorted JSON. */
import { compareCodePoints } from './compare.js'

export function toJSONText(root) {
  return renderNode(root, '') + '\n'
}

function renderNode(node, indent) {
  switch (node.kind) {
    case 'table':
      return renderTable(node, indent)
    case 'array':
    case 'array-of-tables':
      return renderArray(node.items, indent)
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

function renderTable(node, indent) {
  const keys = [...node.entries.keys()].sort(compareCodePoints)
  if (keys.length === 0) return '{}'
  const inner = indent + '  '
  const parts = keys.map((k) => `${inner}${JSON.stringify(k)}: ${renderNode(node.entries.get(k), inner)}`)
  return `{\n${parts.join(',\n')}\n${indent}}`
}

function renderArray(items, indent) {
  if (items.length === 0) return '[]'
  const inner = indent + '  '
  const parts = items.map((v) => `${inner}${renderNode(v, inner)}`)
  return `[\n${parts.join(',\n')}\n${indent}]`
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-XHJacQ/src/keys-output.js","content":"/** Renders a parsed document tree as `<path> <type>` lines, depth first. */
import { compareCodePoints } from './compare.js'

export function toKeysText(root) {
  const lines = []
  walk(root, '', lines)
  return lines.length === 0 ? '' : lines.join('\n') + '\n'
}

function typeOf(node) {
  if (node.kind === 'array-of-tables') return 'array'
  return node.kind
}

function walk(node, path, lines) {
  if (node.kind === 'table') {
    const keys = [...node.entries.keys()].sort(compareCodePoints)
    for (const key of keys) {
      const child = node.entries.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, lines)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((child, index) => {
      const childPath = `${path}[${index}]`
      lines.push(`${childPath} ${typeOf(child)}`)
      walk(child, childPath, lines)
    })
  }
}
