/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { parseDocument, ConfigError } from './document-parser.js'
import { toJSONText } from './json-output.js'
import { toKeysText } from './keys-output.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function finish(code, text, toStdout) {
  const stream = toStdout ? process.stdout : process.stderr
  stream.write(text, () => {
    process.exitCode = code
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    finish(2, 'error: usage: cli.js json|keys\n', false)
    return
  }

  const mode = args[0]
  const input = await readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (err) {
    if (err instanceof ConfigError) {
      finish(2, `error: line ${err.line}: ${err.message}\n`, false)
      return
    }
    throw err
  }

  const output = mode === 'json' ? toJSONText(root) : toKeysText(root)
  finish(0, output, true)
}

main().catch((err) => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
"}

